(() => {
  "use strict";

  const pictures = {
    cat: ["__IMG:reveal-cat__", "猫"],
    panda: ["__IMG:reveal-panda__", "熊猫"],
    bag: ["__IMG:object-schoolbag__", "书包"],
    book: ["__IMG:object-book__", "书"],
    pen: ["__IMG:object-pen__", "钢笔"],
    pencil: ["__IMG:object-pencil__", "铅笔"],
    ruler: ["__IMG:object-ruler__", "尺"],
    window: ["__IMG:object-window__", "窗"],
    door: ["__IMG:object-door__", "门"],
    child: ["__IMG:speaker-child__", "说话的小朋友"],
    partner: ["__IMG:partner-child__", "伙伴"],
  };
  const backupPictures = {
    cat: "data:image/jpeg;base64,", panda: "data:image/jpeg;base64,", bag: "data:image/jpeg;base64,",
    book: "data:image/jpeg;base64,", pen: "data:image/jpeg;base64,", pencil: "data:image/jpeg;base64,",
    ruler: "data:image/jpeg;base64,", window: "data:image/jpeg;base64,", door: "data:image/jpeg;base64,",
    child: "data:image/jpeg;base64,", partner: "data:image/jpeg;base64,",
  };
  const clips = {
    cat: "/api/classroom-media/__STAGE__/media/tts-picture-reveal-13-5207c4254e7fc7a7ff9694108c7b7fb3146afe2030b137492cf46d882ccc1c71.wav", panda: "/api/classroom-media/__STAGE__/media/tts-picture-reveal-7-c61ce5ea8985bf964115c678ca9d596145e9c28ab636bea5932d58001cd214fa.wav", bag: "/api/classroom-media/__STAGE__/media/tts-schoolbag-items-4-9ed38aad7b5046eb6f939619d550480a428b19c69ef1149b1e3a0e48af6f6b22.wav",
    book: "/api/classroom-media/__STAGE__/media/tts-schoolbag-items-8-7856509c0ee5606c91e1a2e92f25c231910ae0f2c0ec2152275dcade0dcec443.wav", pen: "/api/classroom-media/__STAGE__/media/tts-schoolbag-items-11-7200e53a290fd24833125d3254b628bc4326ac2349584d307a91696e9371d8a8.wav", pencil: "/api/classroom-media/__STAGE__/media/tts-schoolbag-items-14-7a89691ced2aa33348388e6e96b90b40dd83c04ebafa8f1f105dcbf59b63ffe8.wav",
    ruler: "/api/classroom-media/__STAGE__/media/tts-schoolbag-items-18-4a68b32647f330db0408e8498d6b5a1d934a4d15e166e7e42c36800f834f4201.wav", this: "/api/classroom-media/__STAGE__/media/tts-speaker-position-16-f47733c2098f58586adb50e7354b06eaaf84b87c3e4b1ae324a9c376ddbc1487.wav", that: "/api/classroom-media/__STAGE__/media/tts-speaker-position-17-17ba7eab916680bdd380f52c5c92015839f55ed315eeaed5984d414f42780443.wav",
    reveal: "/api/classroom-media/__STAGE__/media/tts-picture-reveal-16-9a20bdab6c2fc36fe5e59a523eaa6c993d26418e85a156aea35348d44e954d43.wav", sort: "/api/classroom-media/__STAGE__/media/tts-schoolbag-items-23-8b633ae32309320d2e4cc0d947704657086f207e660244064018f7097d89ba87.wav", puzzle: "/api/classroom-media/__STAGE__/media/tts-puzzle-listen-13-0a7ac563bfb88bfbefa22da6e0a41058111c5a19ce44460a5ef3cd98dbcc9032.wav",
    position: "/api/classroom-media/__STAGE__/media/tts-speaker-position-15-861f68a1aff5b4e5a4fb78b065e903ff26a3331eea5625df3485842088544825.wav", turn: "/api/classroom-media/__STAGE__/media/tts-take-turns-18-1a13e65b4dfdf3d04c578742ba63773fcfe80b15e8bb57114e30e9175c87e072.wav", guessHint: "/api/classroom-media/__STAGE__/media/tts-picture-reveal-18-a79ddf0e28d938d6c18ddda024215349bab8018838732043daca3f5aceaa0b6c.wav",
    sortHint: "/api/classroom-media/__STAGE__/media/tts-schoolbag-items-25-20c8803b09a78ba4e0459ab7349aaa3ce68b7e0177cd0be9ad9ae193156930ae.wav", puzzleHint: "/api/classroom-media/__STAGE__/media/tts-puzzle-listen-14-50ad36493508d2b4259714041c262ad6d2569c72e97a76a54608e280085399a8.wav",
    positionHint: "/api/classroom-media/__STAGE__/media/tts-speaker-position-18-8b8321742440b879180af658e0c1cd9f5030a88226dbc8b4d025c35efe8f5dd0.wav", turnHint: "/api/classroom-media/__STAGE__/media/tts-take-turns-19-766912540a68ec6b0fdbfc8458ad386fdf93a69421ee34430fc861d45d5f2099.wav",
  };
  const activities = {
    "图画还差一点": { mode: "reveal", size: 2, subtitle: "先猜，再看全图" },
    "书包里有什么": { mode: "sort", size: 6, subtitle: "归位，再听音找图" },
    "拼好再来问": { mode: "puzzle", size: 2, subtitle: "拼到缺口里，再听问答" },
    "跟着说话人看": { mode: "position", size: 3, subtitle: "先移小朋友，再听问句" },
    "这一次轮到你问": { mode: "turn", size: 3, subtitle: "把实物卡传给伙伴" },
  };
  const activity = activities[document.title];
  const supplies = ["bag", "book", "pen", "pencil", "ruler"];
  const puzzleRounds = [["pen", "pencil"], ["bag", "book"]];
  const positionRounds = [
    { items: ["window", "door"], prompt: "this" },
    { items: ["pen", "bag"], prompt: "that" },
    { items: ["pencil", "book"], prompt: "this" },
  ];
  const turnItems = ["pen", "pencil", "ruler"];
  const board = K.$("#object-board");
  const actions = K.$("#object-next");
  const listen = K.$("#object-listen");
  const audio = new Audio();
  let narrationAllowed = window.parent === window;
  let audioRevision = 0;
  let round, order, selected, uncovered, completed, placed, side, moved, misses, demonstration;

  function stopAudio() {
    audioRevision += 1;
    audio.pause();
    audio.removeAttribute("src");
    listen.dataset.playing = "false";
  }

  function playClip(key) {
    const source = clips[key];
    if (!source) return;
    if (!narrationAllowed || document.hidden) {
      K.say("等老师讲完，再点喇叭。");
      return;
    }
    const revision = ++audioRevision;
    audio.src = source;
    listen.dataset.playing = "true";
    audio.play().catch(() => {
      if (revision !== audioRevision) return;
      listen.dataset.playing = "false";
      K.say("没听到声音，再点一次喇叭。");
    });
  }

  for (const event of ["ended", "error"]) {
    audio.addEventListener(event, () => { listen.dataset.playing = "false"; });
  }
  window.addEventListener("message", (event) => {
    if (event.source !== parent || event.data?.type !== "MIRA_NARRATION_VISIBILITY") return;
    narrationAllowed = event.data.visible === true;
    if (!narrationAllowed) stopAudio();
  });
  document.addEventListener("visibilitychange", () => { if (document.hidden) stopAudio(); });
  window.addEventListener("pagehide", stopAudio);

  function image(key, target) {
    const [src, label] = pictures[key];
    const img = K.el("img", "", null, target);
    img.src = src;
    img.alt = label;
    img.addEventListener("error", () => {
      if (img.dataset.retried) return;
      img.dataset.retried = "true";
      const backup = backupPictures[key];
      if (backup.startsWith("data:image/")) img.src = backup;
      else img.src = src + "?retry=1";
    });
    return img;
  }

  function pictureButton(key, target, className = "", onClick) {
    const button = K.el("button", "picture-button " + className, null, target);
    button.type = "button";
    button.setAttribute("aria-label", pictures[key][1]);
    image(key, button);
    if (onClick) button.addEventListener("click", onClick);
    return button;
  }

  function tool(label, fn, symbol) {
    const control = K.el("button", "btn green", null, actions);
    control.type = "button";
    K.el("span", "object-action-mark", symbol, control).setAttribute("aria-hidden", "true");
    K.el("span", "", label, control);
    control.addEventListener("click", fn);
    return control;
  }

  function dragOrTap(source, targets, onTap, onDrop) {
    K.drag(source, { targets, onTap, onDrop });
    source.addEventListener("click", (event) => {
      if (event.detail === 0) onTap();
    });
  }

  function sayWrong(message, element) {
    misses += 1;
    K.say(message, "no");
    if (element) K.shake(element);
    if (misses > 1) board.querySelector("[data-help]")?.classList.add("hint");
    K.sfx.no();
  }

  function finishRound(from, message) {
    completed = true;
    K.say(message, "ok");
    K.star(1, from);
    K.sfx.ok();
    K.levels(activity.size, round + 1);
    render();
  }

  function nextRound() {
    stopAudio();
    round += 1;
    if (round === activity.size) {
      K.finish({ title: "做完啦", sub: "你能听、能看，也能再试。", again: startGame });
      return;
    }
    resetRound();
    K.levels(activity.size, round);
    render();
    K.say(activity.subtitle);
  }

  function resetRound() {
    selected = null;
    uncovered = completed = moved = false;
    misses = 0;
    side = round % 2;
    order = K.shuffle(supplies);
  }

  function startGame() {
    stopAudio();
    demonstration = null;
    round = 0;
    K.stars = 0;
    K.star(0);
    K.levels(activity.size, 0);
    placed = new Set();
    resetRound();
    render();
    K.say(activity.subtitle);
  }

  function currentCue() {
    switch (activity.mode) {
      case "reveal": return completed ? (round ? "panda" : "cat") : misses ? "guessHint" : "reveal";
      case "sort": return round ? supplies[round - 1] : misses ? "sortHint" : "sort";
      case "puzzle": return completed ? puzzleRounds[round][0] : misses ? "puzzleHint" : "puzzle";
      case "position": return moved ? positionRounds[round].prompt : misses ? "positionHint" : "position";
      case "turn": return completed ? turnItems[round] : misses ? "turnHint" : "turn";
    }
  }

  listen.addEventListener("click", () => playClip(currentCue()));

  function drawReveal() {
    const animal = round ? "panda" : "cat";
    const isDemo = Boolean(demonstration);
    const choice = isDemo ? (demonstration === "revise" ? "cat" : demonstration === "peek" ? null : "panda") : selected;
    const opened = isDemo ? ["uncover", "revise"].includes(demonstration) : uncovered;
    const frame = K.el("div", "photo-frame", null, board);
    const subject = image(animal, frame);
    if (!opened) {
      subject.alt = "图画露出的一小部分";
      K.el("div", "photo-cover", null, frame);
    }
    const options = K.el("div", "reveal-options", null, board);
    function checkGuess(key, element) {
      if (key !== animal) return sayWrong("先看看耳朵和尾巴。", element);
      selected = key;
      finishRound(element, "你用全图核对了。");
    }
    for (const key of ["panda", "cat"]) {
      const button = pictureButton(key, options, choice === key ? "selected" : "", () => {
        if (uncovered) return checkGuess(key, button);
        selected = key;
        K.say("记下了，掀开看看。", "ok");
        render();
      });
      button.disabled = isDemo || completed;
      if (opened && key === animal) button.dataset.help = "";
      if (completed && key === animal) button.classList.add("success");
    }
    if (isDemo || completed) return;
    if (selected && !uncovered) {
      tool("打开遮片", () => {
        uncovered = true;
        render();
        K.say("看全图。你想改一张吗？", "ok");
      }, "↗");
    } else if (uncovered) {
      tool("确认图片", () => checkGuess(selected, frame), "✓");
    }
  }

  function drawSort() {
    board.dataset.room = "reading";
    if (demonstration && demonstration !== "sort") {
      const keys = ["pen", "pencil"].includes(demonstration) ? ["pen", "pencil"] : [demonstration];
      for (const key of keys) image(key, K.el("div", "photo-frame", null, board));
      const chosen = keys.indexOf(demonstration);
      board.children[chosen].classList.add("teach-hl");
      return;
    }
    if (round > 0) {
      const goal = supplies[round - 1];
      const grid = K.el("div", "listen-options", null, board);
      for (const key of order) {
        const button = pictureButton(key, grid, completed && key === goal ? "success" : "", () => {
          if (key !== goal) return sayWrong("再听一次，留意最后一个词。", button);
          finishRound(button, "你找到了对应的学具。");
        });
        button.disabled = completed;
        if (key === goal) button.dataset.help = "";
      }
      return;
    }
    const grid = K.el("div", "sorting", null, board);
    const slots = new Map();
    function put(key, slot) {
      if (!slot || slot.dataset.item !== key) return sayWrong("再看看形状，试一试。", slot);
      placed.add(key);
      selected = null;
      if (placed.size === supplies.length) return finishRound(slot, "学具都归位了。");
      render();
      K.say("这件放好了。", "ok");
    }
    for (const key of supplies) {
      const stored = placed.has(key) || (demonstration && key === "book");
      const slot = pictureButton(key, grid, stored ? "slot success" : "slot", () => {
        if (selected) put(selected, slot);
      });
      slot.dataset.item = key;
      slot.setAttribute("aria-label", pictures[key][1] + "的归位槽");
      slot.disabled = stored || Boolean(demonstration);
      slots.set(key, slot);
      if (selected === key) slot.dataset.help = "";
    }
    for (const key of order) {
      const card = pictureButton(key, grid, selected === key ? "selected" : "");
      card.disabled = placed.has(key) || Boolean(demonstration);
      if (placed.has(key)) card.style.visibility = "hidden";
      const pick = () => { selected = key; render(); K.say("再选它的归位槽。", "ok"); };
      if (!card.disabled) {
        dragOrTap(card, () => [...slots.values()].filter((slot) => !slot.disabled), pick,
          (_, target) => put(key, target));
      }
    }
  }

  function drawPuzzle() {
    const shownRound = demonstration === "bag-complete" ? 1 : round;
    const [goal, distractor] = puzzleRounds[shownRound];
    const isDemo = Boolean(demonstration);
    const whole = completed || demonstration?.endsWith("-complete");
    const frame = K.el("div", "photo-frame puzzle-frame" + (whole ? " success" : ""), null, board);
    image(goal, frame);
    const tray = K.el("div", "piece-tray", null, board);
    if (whole) return;
    function place(key, target) {
      if (target !== gap || key !== goal) return sayWrong("看接缝，再换一片或一个位置。", frame);
      finishRound(frame, "拼上了，点喇叭听问答。");
    }
    const gap = K.el("button", "puzzle-gap", null, frame);
    gap.type = "button";
    gap.disabled = isDemo;
    gap.setAttribute("aria-label", "拼图缺口");
    gap.addEventListener("click", () => { if (selected) place(selected, gap); });
    const choices = shownRound ? [distractor, goal] : [goal, distractor];
    for (const [index, key] of choices.entries()) {
      const card = K.el("button", "picture-button", null, tray);
      card.type = "button";
      card.id = "piece-option-" + index;
      card.setAttribute("aria-label", index === 0 ? "上方拼片" : "下方拼片");
      const crop = K.el("span", "piece-crop", null, card);
      const partial = image(key, crop);
      partial.alt = "拼图的一片";
      card.disabled = isDemo;
      if (key === goal) card.dataset.help = "";
      if (selected === key || (key === goal && demonstration === "piece")) card.classList.add("selected");
      if (!isDemo) {
        dragOrTap(card, () => [gap], () => {
          selected = key;
          render();
          K.say("再点缺口，试试接得上吗？", "ok");
        }, (_, target) => place(key, target));
      }
    }
  }

  function drawPosition() {
    board.dataset.room = "art";
    const { items, prompt } = positionRounds[round];
    const isDemo = Boolean(demonstration);
    const speaker = demonstration === "swap" ? 1 : isDemo ? 0 : side;
    const goal = prompt === "this" ? speaker : 1 - speaker;
    const layout = K.el("div", "position-layout", null, board);
    items.forEach((key, index) => {
      const card = pictureButton(key, layout, completed && goal === index ? "success" : "", () => {
        if (goal !== index) return sayWrong("先找说话的小朋友在哪边。", card);
        finishRound(card, "你跟着说话人找到了。");
      });
      card.disabled = isDemo || completed || !moved;
      if (index === goal) card.dataset.help = "";
    });
    const spots = [];
    function move(index) {
      if (index === side) return;
      side = index;
      moved = true;
      stopAudio();
      render();
      K.say("位置换了。点喇叭，再选图。", "ok");
    }
    for (const index of [0, 1]) {
      const occupied = speaker === index;
      const spot = K.el("button", "picture-button person-spot" + (occupied ? " occupied" : ""), null, layout);
      spot.type = "button";
      spot.setAttribute("aria-label", index === 0 ? "左边站位" : "右边站位");
      if (occupied) image("child", spot);
      spot.disabled = isDemo || completed || moved;
      if (!spot.disabled) {
        if (occupied) dragOrTap(spot, () => spots.filter((target) => target !== spot), () => {}, (_, target) => {
          if (target) move(spots.indexOf(target));
        });
        else spot.addEventListener("click", () => move(index));
      }
      spots.push(spot);
    }
    if (["near", "far", "swap"].includes(demonstration)) {
      const to = demonstration === "far" ? 1 : speaker;
      const fromX = speaker === 0 ? 135 : 675;
      const toX = to === 0 ? 135 : 675;
      const guide = K.el("div", "position-line", null, layout);
      guide.setAttribute("aria-hidden", "true");
      guide.innerHTML = '<svg width="100%" height="100%" viewBox="0 0 810 40"><path d="M' + fromX + ' 39 L' + toX + ' 6" stroke="#c77e22" stroke-width="7" stroke-linecap="round" fill="none"/></svg>';
      layout.children[to].classList.add("teach-hl");
    }
  }

  function drawTurns() {
    board.dataset.room = "art";
    const demos = { left: "pen", right: "pencil", "beat-pen": "pen", "beat-pencil": "pencil", "new-object": "ruler" };
    const item = demos[demonstration] || turnItems[round];
    const owner = demonstration === "right" ? 1 : side;
    const row = K.el("div", "turn-layout", null, board);
    const people = [];
    const left = pictureButton("child", row, "partner");
    const card = pictureButton(item, row, "turn-card");
    const right = pictureButton("partner", row, "partner");
    people.push(left, right);
    card.dataset.owner = String(owner);
    people[owner].classList.add("asker");
    if (demonstration || completed) {
      for (const control of [left, card, right]) control.disabled = true;
      return;
    }
    function pass(person) {
      const next = people.indexOf(person);
      if (next < 0 || side === next) return sayWrong("先看卡在谁手里，再传给另一位。", person);
      side = next;
      finishRound(person, "换人问了。可以点喇叭听问答。");
    }
    people[1 - owner].dataset.help = "";
    for (const person of people) {
      person.addEventListener("click", () => { if (selected) pass(person); });
    }
    dragOrTap(card, () => people, () => {
      selected = item;
      card.classList.add("selected");
      K.say("再点另一位小朋友。", "ok");
    }, (_, person) => pass(person));
  }

  const draw = { reveal: drawReveal, sort: drawSort, puzzle: drawPuzzle, position: drawPosition, turn: drawTurns };

  function render() {
    board.replaceChildren();
    actions.replaceChildren();
    K.drags = K.drags.filter((entry) => entry.el.isConnected);
    draw[activity.mode]();
    listen.disabled = Boolean(demonstration);
    if (completed && !demonstration) {
      const last = round + 1 === activity.size;
      tool(last ? "完成" : "下一关", nextRound, last ? "✓" : "→");
    }
  }

  K.hud({ icon: "", title: document.title, levels: activity.size });
  K.owl();
  const coverFallback = backupPictures.bag.startsWith("data:image/") ? backupPictures.bag : pictures.bag[0];
  K.ready({ title: document.title, sub: activity.subtitle,
    emoji: '<img class="ready-backup" src="' + coverFallback + '" alt="书包">' });
  K.onStart = startGame;
  K.onState = (state) => {
    if (state.ready) return startGame();
    if (!state.demo) return;
    stopAudio();
    demonstration = state.demo;
    render();
  };
})();
